    and length("exploration_observation"."id") = 36 and length("exploration_observation"."brand_id") = 36
    and length("exploration_observation"."owner_id") between 1 and 128
    and length("exploration_observation"."question_text") between 1 and 4000
    and length("exploration_observation"."answer_text") between 1 and 8000
    and length("exploration_observation"."operation_id") = 36
    and length("exploration_observation"."created_at") between 20 and 40)
);

CREATE UNIQUE INDEX `exploration_observation_operation_uidx` ON `exploration_observation` (`brand_id`,`operation_id`);
CREATE INDEX `exploration_observation_owner_idx` ON `exploration_observation` (`owner_id`,`brand_id`,`created_at`,`id`);
CREATE TABLE `monitoring_attempt` (
	`id` text PRIMARY KEY NOT NULL,
	`slot_id` text NOT NULL,
	`run_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`kind` text NOT NULL,
	`ordinal` integer NOT NULL,
	`transport` text NOT NULL,
	`synthetic` integer NOT NULL,
	`disposition` text NOT NULL,
	`raw_text` text,
	`currency` text,
	`upper_minor` integer,
	`actual_minor` integer,
	`cost_state` text NOT NULL,
	`quota_attempt_id` text,
	`late` integer DEFAULT 0 NOT NULL,
	`created_at` text NOT NULL,
	`receipt` text,
	FOREIGN KEY (`slot_id`) REFERENCES `monitoring_slot`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "monitoring_attempt_state_check" CHECK("monitoring_attempt"."ordinal" between 1 and 20 and "monitoring_attempt"."synthetic" in (0, 1) and "monitoring_attempt"."late" in (0, 1)
    and "monitoring_attempt"."transport" in ('isolated', 'official_api')
    and (("monitoring_attempt"."transport" = 'isolated' and "monitoring_attempt"."synthetic" = 1) or ("monitoring_attempt"."transport" = 'official_api' and "monitoring_attempt"."synthetic" = 0))
    and ("monitoring_attempt"."currency" is null or length("monitoring_attempt"."currency") = 3)
    and ("monitoring_attempt"."upper_minor" is null or "monitoring_attempt"."upper_minor" >= 0)
    and (
      ("monitoring_attempt"."cost_state" in ('none', 'pending', 'unknown') and "monitoring_attempt"."actual_minor" is null)
      or ("monitoring_attempt"."cost_state" = 'known' and "monitoring_attempt"."actual_minor" is not null and "monitoring_attempt"."actual_minor" >= 0)
    )
    and (
      ("monitoring_attempt"."kind" = 'sampling' and "monitoring_attempt"."ordinal" <= 3 and "monitoring_attempt"."disposition" in ('pending', 'adopted', 'safe_failure', 'unknown', 'late'))
      or ("monitoring_attempt"."kind" = 'analysis' and "monitoring_attempt"."disposition" = 'analysis_reuse' and "monitoring_attempt"."cost_state" = 'none')
    ))
);

CREATE UNIQUE INDEX `monitoring_attempt_ordinal_uidx` ON `monitoring_attempt` (`slot_id`,`kind`,`ordinal`);
CREATE UNIQUE INDEX `monitoring_attempt_adopted_uidx` ON `monitoring_attempt` (`slot_id`) WHERE "monitoring_attempt"."disposition" = 'adopted';
CREATE INDEX `monitoring_attempt_run_idx` ON `monitoring_attempt` (`run_id`,`slot_id`,`ordinal`);
CREATE INDEX `monitoring_attempt_brand_idx` ON `monitoring_attempt` (`brand_id`,`created_at`,`id`);
CREATE TABLE `monitoring_run` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`operation_id` text NOT NULL,
	`fingerprint` text NOT NULL,
	`track` text NOT NULL,
	`prompt_set_id` text NOT NULL,
	`prompt_set_version` integer NOT NULL,
	`repeat_count` integer NOT NULL,
	`question_count` integer NOT NULL,
	`natural_count` integer NOT NULL,
	`channel_count` integer NOT NULL,
	`slot_count` integer NOT NULL,
	`region` text NOT NULL,
	`language` text NOT NULL,
	`requested_network_mode` text NOT NULL,
	`currency` text,
	`upper_minor` integer,
	`estimate_high_minor` integer,
	`customer_payable_minor` integer NOT NULL,
	`status` text NOT NULL,
	`sampling_complete` integer NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "monitoring_run_scope_check" CHECK("monitoring_run"."track" in ('model_api', 'consumer_ui')
    and "monitoring_run"."repeat_count" between 1 and 3
    and "monitoring_run"."question_count" > 0 and "monitoring_run"."natural_count" between 0 and "monitoring_run"."question_count"
    and "monitoring_run"."channel_count" > 0 and "monitoring_run"."slot_count" = "monitoring_run"."question_count" * "monitoring_run"."channel_count" * "monitoring_run"."repeat_count"
    and length("monitoring_run"."region") = 2 and length("monitoring_run"."language") between 2 and 40
    and "monitoring_run"."requested_network_mode" in ('on', 'off', 'unknown')
    and "monitoring_run"."status" in ('queued', 'running', 'paused', 'succeeded', 'partial', 'failed', 'cancelled')
    and "monitoring_run"."sampling_complete" in (0, 1) and "monitoring_run"."customer_payable_minor" = 0
    and (("monitoring_run"."status" in ('queued', 'running', 'paused') and "monitoring_run"."sampling_complete" = 0)
      or "monitoring_run"."status" in ('succeeded', 'partial', 'failed', 'cancelled'))
    and (
      ("monitoring_run"."track" = 'consumer_ui' and "monitoring_run"."currency" is null and "monitoring_run"."upper_minor" is null and "monitoring_run"."estimate_high_minor" is null)
      or ("monitoring_run"."track" = 'model_api' and "monitoring_run"."currency" is not null and length("monitoring_run"."currency") = 3
        and "monitoring_run"."upper_minor" >= 0 and "monitoring_run"."estimate_high_minor" = "monitoring_run"."upper_minor" * "monitoring_run"."slot_count")
    ))
);

CREATE UNIQUE INDEX `monitoring_run_operation_uidx` ON `monitoring_run` (`brand_id`,`operation_id`);
CREATE INDEX `monitoring_run_operation_idx` ON `monitoring_run` (`operation_id`);
CREATE INDEX `monitoring_run_brand_recent_idx` ON `monitoring_run` (`brand_id`,`created_at`,`id`);
CREATE TABLE `monitoring_slot` (
	`id` text PRIMARY KEY NOT NULL,
	`run_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`question_id` text NOT NULL,
	`natural_question` integer NOT NULL,
	`channel_id` text NOT NULL,
	`channel_version` integer NOT NULL,
	`repeat_index` integer NOT NULL,
	`reservation_id` text,
	`status` text NOT NULL,
	`created_at` text NOT NULL,
	`adopted_attempt_id` text,
	`late` integer DEFAULT 0 NOT NULL,
	FOREIGN KEY (`run_id`) REFERENCES `monitoring_run`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "monitoring_slot_state_check" CHECK("monitoring_slot"."natural_question" in (0, 1) and "monitoring_slot"."repeat_index" between 1 and 3
    and "monitoring_slot"."channel_version" > 0 and "monitoring_slot"."late" in (0, 1)
    and "monitoring_slot"."status" in ('queued', 'running', 'paused', 'succeeded', 'failed', 'cancelled', 'reconciliation_required')
    and (("monitoring_slot"."status" = 'succeeded' and "monitoring_slot"."adopted_attempt_id" is not null)
      or ("monitoring_slot"."status" <> 'succeeded' and "monitoring_slot"."adopted_attempt_id" is null)))
);

CREATE UNIQUE INDEX `monitoring_slot_position_uidx` ON `monitoring_slot` (`run_id`,`question_id`,`channel_id`,`repeat_index`);
CREATE INDEX `monitoring_slot_brand_idx` ON `monitoring_slot` (`brand_id`,`run_id`);
CREATE INDEX `monitoring_slot_reservation_idx` ON `monitoring_slot` (`brand_id`,`reservation_id`);
CREATE TABLE `run_protocol_pin` (
	`run_id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`protocol_id` text NOT NULL,
	`version` integer NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`owner_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`run_id`) REFERENCES `monitoring_run`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`protocol_id`,`version`) REFERENCES `sampling_protocol`(`protocol_id`,`version`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "run_protocol_pin_state_check" CHECK("run_protocol_pin"."version" > 0
    and length("run_protocol_pin"."run_id") = 36 and length("run_protocol_pin"."brand_id") = 36
    and length("run_protocol_pin"."owner_id") between 1 and 128 and length("run_protocol_pin"."protocol_id") = 36
    and length("run_protocol_pin"."created_at") between 20 and 40)
);

CREATE INDEX `run_protocol_pin_protocol_idx` ON `run_protocol_pin` (`protocol_id`,`version`);
CREATE INDEX `run_protocol_pin_owner_idx` ON `run_protocol_pin` (`owner_id`,`created_at`,`run_id`);
CREATE TABLE `sampling_protocol` (
	`id` text PRIMARY KEY NOT NULL,
	`protocol_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`version` integer NOT NULL,
	`new_session_required` integer NOT NULL,
	`search_required` integer NOT NULL,
	`target_region` text NOT NULL,
	`timezone` text NOT NULL,
	`status` text NOT NULL,
	`fingerprint` text NOT NULL,
	`operation_id` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`owner_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "sampling_protocol_state_check" CHECK("sampling_protocol"."version" > 0
    and "sampling_protocol"."new_session_required" in (0, 1) and "sampling_protocol"."search_required" in (0, 1)
    and "sampling_protocol"."status" in ('draft', 'frozen')
    and length("sampling_protocol"."id") = 36 and length("sampling_protocol"."protocol_id") = 36
    and length("sampling_protocol"."brand_id") = 36 and length("sampling_protocol"."owner_id") between 1 and 128
    and length("sampling_protocol"."target_region") = 2 and length("sampling_protocol"."timezone") between 1 and 64
    and length("sampling_protocol"."fingerprint") = 64 and length("sampling_protocol"."operation_id") = 36
    and length("sampling_protocol"."created_at") between 20 and 40)
);

CREATE UNIQUE INDEX `sampling_protocol_fingerprint_uidx` ON `sampling_protocol` (`protocol_id`,`fingerprint`);
CREATE UNIQUE INDEX `sampling_protocol_operation_uidx` ON `sampling_protocol` (`brand_id`,`operation_id`);
CREATE INDEX `sampling_protocol_owner_idx` ON `sampling_protocol` (`owner_id`,`created_at`,`id`);
CREATE INDEX `sampling_protocol_family_idx` ON `sampling_protocol` (`owner_id`,`protocol_id`,`version`);
CREATE UNIQUE INDEX `sampling_protocol_version_key` ON `sampling_protocol` (`protocol_id`,`version`);
CREATE TABLE `answer_analysis_draft` (
	`id` text PRIMARY KEY NOT NULL,
	`observation_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`mentioned` text NOT NULL,
	`recommended` text NOT NULL,
	`official_site_cited` text NOT NULL,
	`status` text NOT NULL,
	`model_name` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`observation_id`) REFERENCES `answer_observation`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "answer_analysis_draft_state_check" CHECK("answer_analysis_draft"."mentioned" in ('true', 'false', 'unknown')
    and "answer_analysis_draft"."recommended" in ('true', 'false', 'unknown')
    and "answer_analysis_draft"."official_site_cited" in ('true', 'false', 'unknown')
    and "answer_analysis_draft"."status" in ('draft', 'applied', 'dismissed')
    and length("answer_analysis_draft"."model_name") between 1 and 128
    and length("answer_analysis_draft"."owner_id") between 1 and 128
    and length("answer_analysis_draft"."created_at") between 20 and 40)
);

CREATE INDEX `answer_analysis_draft_observation_idx` ON `answer_analysis_draft` (`observation_id`,`created_at`);
CREATE TABLE `answer_analysis_version` (
	`id` text PRIMARY KEY NOT NULL,
	`observation_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`version` integer NOT NULL,
	`entity_version` integer NOT NULL,
	`rule_version` text NOT NULL,
	`mentioned` text NOT NULL,
	`recommended` text NOT NULL,
	`official_site_cited` text NOT NULL,
	`evidence_span` text,
	`status` text NOT NULL,
	`revised_from` text,
	`reason` text,
	`reviewer_id` text,
	`created_at` text NOT NULL,
	FOREIGN KEY (`observation_id`) REFERENCES `answer_observation`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "answer_analysis_state_check" CHECK("answer_analysis_version"."version" > 0 and "answer_analysis_version"."entity_version" > 0
    and "answer_analysis_version"."mentioned" in ('true', 'false', 'unknown')
    and "answer_analysis_version"."recommended" in ('true', 'false', 'unknown')
    and "answer_analysis_version"."official_site_cited" in ('true', 'false', 'unknown')
    and "answer_analysis_version"."status" in ('pending', 'classified', 'needs_review', 'revised')
    and ("answer_analysis_version"."revised_from" is null or "answer_analysis_version"."revised_from" <> "answer_analysis_version"."id"))
);

CREATE UNIQUE INDEX `answer_analysis_version_uidx` ON `answer_analysis_version` (`observation_id`,`version`);
CREATE INDEX `answer_analysis_brand_idx` ON `answer_analysis_version` (`brand_id`,`observation_id`,`version`);
CREATE TABLE `answer_citation` (
	`id` text PRIMARY KEY NOT NULL,
	`observation_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`raw_url` text NOT NULL,
	`normalized_url` text NOT NULL,
	`citation_origin` text NOT NULL,
	`position_label` text,
	`ownership` text NOT NULL,
	`page_status` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`observation_id`) REFERENCES `answer_observation`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "answer_citation_state_check" CHECK("answer_citation"."citation_origin" in ('provider_native', 'consumer_visible', 'search_candidate', 'analyst_found', 'custom_pipeline')
    and "answer_citation"."ownership" in ('owned_domain', 'owned_account', 'competitor', 'third_party', 'unknown')
    and "answer_citation"."page_status" in ('unknown', 'reachable', 'restricted', 'not_applicable'))
);

CREATE INDEX `answer_citation_observation_idx` ON `answer_citation` (`observation_id`,`id`);
CREATE INDEX `answer_citation_brand_idx` ON `answer_citation` (`brand_id`,`observation_id`);
CREATE TABLE `answer_observation` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`slot_id` text,
	`attempt_id` text,
	`source_mode` text NOT NULL,
	`capture_method` text NOT NULL,
	`question_text` text NOT NULL,
	`answer_text` text NOT NULL,
	`fingerprint` text NOT NULL,
	`captured_at` text NOT NULL,
	`region` text NOT NULL,
	`language` text NOT NULL,
	`requested_network_mode` text NOT NULL,
	`entity_version` integer NOT NULL,
	`citation_set_state` text NOT NULL,
	`evidence_state` text NOT NULL,
	`locator_ref` text,
	`collector_id` text,
	`missing_reason` text,
	`created_at` text NOT NULL,
	`target_region` text NOT NULL,
	`observed_region` text DEFAULT 'unknown' NOT NULL,
	`new_session` text DEFAULT 'unknown' NOT NULL,
	`product_mode` text DEFAULT 'unknown' NOT NULL,
	`network_trigger` text DEFAULT 'unknown' NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`slot_id`) REFERENCES `monitoring_slot`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`attempt_id`) REFERENCES `monitoring_attempt`(`id`) ON UPDATE no action ON DELETE set null,
	CONSTRAINT "answer_observation_state_check" CHECK("answer_observation"."source_mode" in ('model_api', 'consumer_ui')
    and "answer_observation"."capture_method" in ('official_api', 'manual', 'assisted', 'isolated')
    and "answer_observation"."citation_set_state" in ('complete', 'partial', 'unsupported', 'missing')
    and "answer_observation"."evidence_state" in ('draft_evidence', 'complete', 'incomplete', 'contested')
    and "answer_observation"."entity_version" > 0 and length("answer_observation"."fingerprint") = 64
    and length("answer_observation"."region") = 2 and length("answer_observation"."language") between 2 and 40
    and "answer_observation"."requested_network_mode" in ('on', 'off', 'unknown')
    and length("answer_observation"."target_region") = 2
    and ("answer_observation"."observed_region" = 'unknown' or length("answer_observation"."observed_region") = 2)
    and "answer_observation"."new_session" in ('true', 'false', 'unknown')
    and "answer_observation"."product_mode" in ('true', 'false', 'unknown')
    and "answer_observation"."network_trigger" in ('triggered', 'not_triggered', 'unknown')
    and (
      ("answer_observation"."evidence_state" = 'draft_evidence')
      or ("answer_observation"."evidence_state" in ('complete', 'incomplete', 'contested') and length("answer_observation"."answer_text") > 0)
    )
    and (
      ("answer_observation"."source_mode" = 'consumer_ui' and "answer_observation"."capture_method" in ('manual', 'assisted'))
      or ("answer_observation"."source_mode" = 'model_api' and "answer_observation"."capture_method" in ('official_api', 'isolated', 'assisted'))
    ))
);

CREATE UNIQUE INDEX `answer_observation_slot_uidx` ON `answer_observation` (`slot_id`) WHERE "answer_observation"."slot_id" is not null and "answer_observation"."evidence_state" in ('complete', 'incomplete', 'contested');
CREATE INDEX `answer_observation_brand_idx` ON `answer_observation` (`brand_id`,`created_at`,`id`);
CREATE INDEX `answer_observation_owner_idx` ON `answer_observation` (`owner_id`,`created_at`,`id`);
CREATE TABLE `optimization_action_draft` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`evidence_ids` text NOT NULL,
	`gap_type` text NOT NULL,
	`observed_gap` text NOT NULL,
	`hypothesis` text NOT NULL,
	`assumption_level` text NOT NULL,
	`question_cluster` text NOT NULL,
	`target_page` text NOT NULL,
	`status` text NOT NULL,
	`model_name` text NOT NULL,
	`task_id` text,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "optimization_action_draft_state_check" CHECK("optimization_action_draft"."gap_type" in ('fact_error', 'name_confusion', 'key_content_missing', 'page_unreadable', 'citation_gap', 'needs_evidence')
    and "optimization_action_draft"."assumption_level" in ('observed_absence', 'verified', 'pending')
    and "optimization_action_draft"."status" in ('draft', 'confirmed', 'dismissed')
    and (
      ("optimization_action_draft"."status" = 'confirmed' and "optimization_action_draft"."task_id" is not null)
      or ("optimization_action_draft"."status" <> 'confirmed' and "optimization_action_draft"."task_id" is null)
    )
    and length("optimization_action_draft"."model_name") between 1 and 128
    and length("optimization_action_draft"."owner_id") between 1 and 128
    and length("optimization_action_draft"."created_at") between 20 and 40
    and length("optimization_action_draft"."evidence_ids") between 38 and 400
    and length("optimization_action_draft"."observed_gap") between 1 and 500
    and length("optimization_action_draft"."hypothesis") between 1 and 500
    and length("optimization_action_draft"."question_cluster") > 0
    and length("optimization_action_draft"."target_page") > 0)
);

CREATE INDEX `optimization_action_draft_owner_idx` ON `optimization_action_draft` (`owner_id`,`brand_id`,`status`,`created_at`,`id`);
CREATE TABLE `optimization_finding` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`gap_type` text NOT NULL,
	`question_cluster` text NOT NULL,
	`target_page` text NOT NULL,
	`observation_id` text,
	`analysis_version_id` text,
	`evidence_summary` text NOT NULL,
	`problem_statement` text NOT NULL,
	`hypothesis` text NOT NULL,
	`assumption_level` text NOT NULL,
	`steps_json` text NOT NULL,
	`completion_criteria` text NOT NULL,
	`retest_method` text NOT NULL,
	`business_importance` integer NOT NULL,
	`estimated_effort` integer NOT NULL,
	`verified_evidence` integer NOT NULL,
	`privacy_risk` integer NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "optimization_finding_state_check" CHECK("optimization_finding"."gap_type" in ('fact_error', 'name_confusion', 'key_content_missing', 'page_unreadable', 'citation_gap', 'needs_evidence')
    and "optimization_finding"."assumption_level" in ('observed_absence', 'verified', 'pending')
    and "optimization_finding"."business_importance" between 1 and 3
    and "optimization_finding"."estimated_effort" between 1 and 5
    and "optimization_finding"."verified_evidence" in (0, 1)
    and "optimization_finding"."privacy_risk" in (0, 1)
    and length("optimization_finding"."question_cluster") > 0
    and length("optimization_finding"."target_page") > 0)
);

CREATE INDEX `optimization_finding_brand_idx` ON `optimization_finding` (`brand_id`,`created_at`,`id`);
CREATE INDEX `optimization_finding_owner_idx` ON `optimization_finding` (`owner_id`,`created_at`,`id`);
CREATE INDEX `optimization_finding_dedupe_idx` ON `optimization_finding` (`brand_id`,`question_cluster`,`target_page`,`gap_type`);
CREATE TABLE `optimization_task` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`primary_finding_id` text NOT NULL,
	`gap_type` text NOT NULL,
	`question_cluster` text NOT NULL,
	`target_page` text NOT NULL,
	`title` text NOT NULL,
	`status` text NOT NULL,
	`priority_bucket` text NOT NULL,
	`manual_rank` integer,
	`reorder_reason` text,
	`completion_note` text,
	`dismiss_reason` text,
	`retest_conclusion` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`primary_finding_id`) REFERENCES `optimization_finding`(`id`) ON UPDATE no action ON DELETE restrict,
	CONSTRAINT "optimization_task_state_check" CHECK("optimization_task"."gap_type" in ('fact_error', 'name_confusion', 'key_content_missing', 'page_unreadable', 'citation_gap', 'needs_evidence')
    and "optimization_task"."status" in ('todo', 'doing', 'blocked', 'implemented', 'retest_pending', 'closed', 'dismissed')
    and "optimization_task"."priority_bucket" in ('urgent', 'normal')
    and ("optimization_task"."manual_rank" is null or "optimization_task"."manual_rank" > 0)
    and (
      ("optimization_task"."status" = 'dismissed' and "optimization_task"."dismiss_reason" is not null)
      or ("optimization_task"."status" <> 'dismissed')
    )
    and (
      ("optimization_task"."manual_rank" is not null and "optimization_task"."reorder_reason" is not null)
      or ("optimization_task"."manual_rank" is null)
    ))
);

CREATE UNIQUE INDEX `optimization_task_open_dedupe_uidx` ON `optimization_task` (`brand_id`,`question_cluster`,`target_page`,`gap_type`) WHERE "optimization_task"."status" not in ('closed', 'dismissed');
CREATE INDEX `optimization_task_brand_status_idx` ON `optimization_task` (`brand_id`,`status`,`created_at`,`id`);
CREATE INDEX `optimization_task_owner_idx` ON `optimization_task` (`owner_id`,`updated_at`,`id`);
CREATE TABLE `optimization_task_evidence` (
	`task_id` text NOT NULL,
	`finding_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`created_at` text NOT NULL,
	PRIMARY KEY(`task_id`, `finding_id`),
	FOREIGN KEY (`task_id`) REFERENCES `optimization_task`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`finding_id`) REFERENCES `optimization_finding`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE INDEX `optimization_task_evidence_brand_idx` ON `optimization_task_evidence` (`brand_id`,`task_id`,`finding_id`);
CREATE TABLE `page_check_record` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`task_id` text,
	`url` text NOT NULL,
	`normalized_url` text NOT NULL,
	`checked_at` text NOT NULL,
	`access_condition` text NOT NULL,
	`public_status` text NOT NULL,
	`title` text,
	`body_excerpt` text,
	`key_facts_json` text NOT NULL,
	`discoverability_notes` text NOT NULL,
	`contains_executable_instructions` integer NOT NULL,
	`manual_evidence_ref` text,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`task_id`) REFERENCES `optimization_task`(`id`) ON UPDATE no action ON DELETE set null,
	CONSTRAINT "page_check_state_check" CHECK("page_check_record"."public_status" in ('reachable', 'restricted', 'pending_verification', 'not_applicable')
    and "page_check_record"."contains_executable_instructions" in (0, 1)
    and length("page_check_record"."url") > 0
    and length("page_check_record"."normalized_url") > 0)
);

CREATE INDEX `page_check_brand_idx` ON `page_check_record` (`brand_id`,`checked_at`,`id`);
CREATE INDEX `page_check_owner_idx` ON `page_check_record` (`owner_id`,`checked_at`,`id`);
CREATE TABLE `channel_profile` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`channel_key` text NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "channel_profile_state_check" CHECK(length("channel_profile"."channel_key") between 1 and 64
    and length("channel_profile"."created_at") between 20 and 40
    and length("channel_profile"."updated_at") between 20 and 40)
);

CREATE UNIQUE INDEX `channel_profile_brand_channel_uidx` ON `channel_profile` (`brand_id`,`channel_key`);
CREATE INDEX `channel_profile_owner_idx` ON `channel_profile` (`owner_id`,`brand_id`,`updated_at`,`id`);
CREATE TABLE `channel_profile_version` (
	`id` text PRIMARY KEY NOT NULL,
	`profile_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`channel_key` text NOT NULL,
	`max_characters` integer,
	`note` text NOT NULL,
	`version_number` integer NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`profile_id`) REFERENCES `channel_profile`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "channel_profile_version_state_check" CHECK(length("channel_profile_version"."channel_key") between 1 and 64
    and ("channel_profile_version"."max_characters" is null or "channel_profile_version"."max_characters" between 1 and 1000000)
    and length("channel_profile_version"."note") between 1 and 2000
    and "channel_profile_version"."version_number" between 1 and 1000000
    and length("channel_profile_version"."created_at") between 20 and 40)
);

CREATE UNIQUE INDEX `channel_profile_version_number_uidx` ON `channel_profile_version` (`profile_id`,`version_number`);
CREATE INDEX `channel_profile_version_owner_idx` ON `channel_profile_version` (`owner_id`,`brand_id`,`channel_key`,`version_number`,`id`);
CREATE TABLE `content_approval` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`content_version_id` text NOT NULL,
	`content_fingerprint` text NOT NULL,
	`fact_version_ids_json` text NOT NULL,
	`decision` text NOT NULL,
	`actor_id` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`content_version_id`) REFERENCES `content_version`(`id`) ON UPDATE no action ON DELETE restrict,
	CONSTRAINT "content_approval_state_check" CHECK("content_approval"."decision" in ('approved', 'rejected')
    and length("content_approval"."content_fingerprint") > 0
    and length("content_approval"."fact_version_ids_json") > 1)
);

CREATE INDEX `content_approval_version_idx` ON `content_approval` (`content_version_id`,`created_at`,`id`);
CREATE INDEX `content_approval_brand_idx` ON `content_approval` (`brand_id`,`created_at`,`id`);
CREATE TABLE `content_asset` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`kind` text NOT NULL,
	`source` text NOT NULL,
	`rights_statement` text NOT NULL,
	`visibility` text NOT NULL,
	`review_status` text NOT NULL,
	`content_ref` text NOT NULL,
	`fingerprint` text NOT NULL,
	`created_at` text NOT NULL,
	`stored_object_id` text,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "content_asset_state_check" CHECK("content_asset"."kind" in ('cover', 'inline', 'other')
    and "content_asset"."visibility" in ('public', 'internal')
    and "content_asset"."review_status" in ('pending', 'approved', 'rejected')
    and length("content_asset"."content_ref") > 0
    and length("content_asset"."fingerprint") > 0)
);

CREATE INDEX `content_asset_brand_idx` ON `content_asset` (`brand_id`,`created_at`,`id`);
CREATE INDEX `content_asset_owner_idx` ON `content_asset` (`owner_id`,`created_at`,`id`);
CREATE UNIQUE INDEX `content_asset_object_uidx` ON `content_asset` (`stored_object_id`) WHERE "content_asset"."stored_object_id" is not null;
CREATE TABLE `content_batch` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`status` text NOT NULL,
	`reservation_id` text,
	`operation_id` text NOT NULL,
	`cost_ledger_json` text NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "content_batch_state_check" CHECK("content_batch"."status" in ('queued', 'running', 'paused', 'partial', 'completed', 'cancelled')
    and length("content_batch"."cost_ledger_json") > 1)
);

CREATE UNIQUE INDEX `content_batch_operation_uidx` ON `content_batch` (`brand_id`,`operation_id`);
CREATE INDEX `content_batch_brand_idx` ON `content_batch` (`brand_id`,`updated_at`,`id`);
CREATE INDEX `content_batch_owner_idx` ON `content_batch` (`owner_id`,`updated_at`,`id`);
CREATE TABLE `content_batch_unit` (
	`id` text PRIMARY KEY NOT NULL,
	`batch_id` text NOT NULL,
	`brief_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`status` text NOT NULL,
	`attempt_count` integer NOT NULL,
	`content_version_id` text,
	`last_error` text,
	`blocked_reason` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`batch_id`) REFERENCES `content_batch`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`brief_id`) REFERENCES `content_brief`(`id`) ON UPDATE no action ON DELETE restrict,
	CONSTRAINT "content_batch_unit_state_check" CHECK("content_batch_unit"."status" in ('queued', 'running', 'succeeded', 'failed', 'blocked')
    and "content_batch_unit"."attempt_count" >= 0)
);

CREATE INDEX `content_batch_unit_batch_idx` ON `content_batch_unit` (`batch_id`,`status`,`id`);
CREATE INDEX `content_batch_unit_brand_idx` ON `content_batch_unit` (`brand_id`,`updated_at`,`id`);
CREATE TABLE `content_brief` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`plan_id` text,
	`optimization_task_id` text,
	`status` text NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`plan_id`) REFERENCES `content_plan`(`id`) ON UPDATE no action ON DELETE set null,
	CONSTRAINT "content_brief_state_check" CHECK("content_brief"."status" in ('draft', 'confirmed', 'invalidated'))
);

CREATE INDEX `content_brief_brand_idx` ON `content_brief` (`brand_id`,`updated_at`,`id`);
CREATE INDEX `content_brief_owner_idx` ON `content_brief` (`owner_id`,`updated_at`,`id`);
CREATE TABLE `content_brief_version` (
	`id` text PRIMARY KEY NOT NULL,
	`brief_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`revision` integer NOT NULL,
	`audience` text NOT NULL,
	`target_gap` text NOT NULL,
	`applicable_boundary` text NOT NULL,
	`primary_page` text NOT NULL,
	`conversion_action` text NOT NULL,
	`template_kind` text NOT NULL,
	`title_candidates_json` text NOT NULL,
	`fact_version_ids_json` text NOT NULL,
	`competitor_source` text,
	`confirmed_at` text,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`brief_id`) REFERENCES `content_brief`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "content_brief_version_state_check" CHECK("content_brief_version"."revision" > 0
    and "content_brief_version"."template_kind" in ('fact_faq', 'scenario_solution', 'verifiable_comparison')
    and length("content_brief_version"."title_candidates_json") > 1
    and length("content_brief_version"."fact_version_ids_json") > 1)
);

CREATE UNIQUE INDEX `content_brief_version_rev_uidx` ON `content_brief_version` (`brief_id`,`revision`);
CREATE INDEX `content_brief_version_brand_idx` ON `content_brief_version` (`brand_id`,`created_at`,`id`);
CREATE TABLE `content_channel_variant` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`content_version_id` text NOT NULL,
	`channel` text NOT NULL,
	`body_markdown` text NOT NULL,
	`approval_status` text NOT NULL,
	`approval_id` text,
	`needs_own_approval` integer NOT NULL,
	`blocked` integer DEFAULT 0 NOT NULL,
	`fingerprint` text NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	`channel_profile_version_id` text,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`content_version_id`) REFERENCES `content_version`(`id`) ON UPDATE no action ON DELETE restrict,
	FOREIGN KEY (`approval_id`) REFERENCES `content_approval`(`id`) ON UPDATE no action ON DELETE restrict,
	FOREIGN KEY (`channel_profile_version_id`) REFERENCES `channel_profile_version`(`id`) ON UPDATE no action ON DELETE restrict,
	CONSTRAINT "content_channel_variant_state_check" CHECK("content_channel_variant"."approval_status" in ('draft', 'approved')
    and "content_channel_variant"."needs_own_approval" in (0, 1)
    and "content_channel_variant"."blocked" in (0, 1)
    and length("content_channel_variant"."channel") > 0
    and length("content_channel_variant"."body_markdown") > 0
    and length("content_channel_variant"."fingerprint") > 0
    and length("content_channel_variant"."created_at") between 20 and 40
    and length("content_channel_variant"."updated_at") between 20 and 40)
);

CREATE UNIQUE INDEX `content_channel_variant_channel_uidx` ON `content_channel_variant` (`content_version_id`,`channel`);
CREATE UNIQUE INDEX `content_channel_variant_approval_uidx` ON `content_channel_variant` (`approval_id`);
CREATE INDEX `content_channel_variant_owner_idx` ON `content_channel_variant` (`owner_id`,`brand_id`,`updated_at`,`id`);
CREATE TABLE `content_delivery_package` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`content_version_id` text NOT NULL,
	`approval_id` text,
	`target_channel` text NOT NULL,
	`kind` text NOT NULL,
	`content_fingerprint` text NOT NULL,
	`fact_version_ids_json` text NOT NULL,
	`labeling_profile_version` text NOT NULL,
	`do_not_reuse` integer DEFAULT 0 NOT NULL,
	`non_publishable` integer DEFAULT 0 NOT NULL,
	`manifest_json` text NOT NULL,
	`files_json` text NOT NULL,
	`package_fingerprint` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`content_version_id`) REFERENCES `content_version`(`id`) ON UPDATE no action ON DELETE restrict,
	FOREIGN KEY (`approval_id`) REFERENCES `content_approval`(`id`) ON UPDATE no action ON DELETE restrict,
	CONSTRAINT "content_delivery_package_state_check" CHECK("content_delivery_package"."kind" in ('formal', 'review')
    and "content_delivery_package"."do_not_reuse" in (0, 1)
    and "content_delivery_package"."non_publishable" in (0, 1)
    and ("content_delivery_package"."kind" = 'review' or ("content_delivery_package"."non_publishable" = 0 and "content_delivery_package"."approval_id" is not null))
    and length("content_delivery_package"."manifest_json") > 1
    and length("content_delivery_package"."files_json") > 1
    and length("content_delivery_package"."package_fingerprint") > 0)
);

CREATE INDEX `content_delivery_package_version_idx` ON `content_delivery_package` (`content_version_id`,`created_at`,`id`);
CREATE INDEX `content_delivery_package_brand_idx` ON `content_delivery_package` (`brand_id`,`created_at`,`id`);
CREATE TABLE `content_export_job` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`operation_id` text NOT NULL,
	`status` text NOT NULL,
	`selection_json` text NOT NULL,
	`preflight_json` text NOT NULL,
	`chosen_subset_json` text NOT NULL,
	`result_package_ids_json` text NOT NULL,
	`error` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "content_export_job_state_check" CHECK("content_export_job"."status" in ('queued', 'ready', 'failed')
    and length("content_export_job"."selection_json") > 1
    and length("content_export_job"."preflight_json") > 1
    and length("content_export_job"."chosen_subset_json") > 1
    and length("content_export_job"."result_package_ids_json") > 1)
);

CREATE UNIQUE INDEX `content_export_job_operation_uidx` ON `content_export_job` (`brand_id`,`operation_id`);
CREATE INDEX `content_export_job_owner_idx` ON `content_export_job` (`owner_id`,`updated_at`,`id`);
CREATE TABLE `content_maintenance_page` (
	`id` text PRIMARY KEY NOT NULL,
	`task_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`page_id` text NOT NULL,
	`draft_id` text NOT NULL,
	`page_url` text NOT NULL,
	`channel` text NOT NULL,
	`planned_on` text,
	`verified_on` text,
	`status` text NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`task_id`) REFERENCES `content_maintenance_task`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`draft_id`) REFERENCES `content_version`(`id`) ON UPDATE no action ON DELETE restrict,
	CONSTRAINT "content_maintenance_page_state_check" CHECK("content_maintenance_page"."status" in ('planned', 'verified', 'blocked')
    and length("content_maintenance_page"."channel") between 1 and 64
    and length("content_maintenance_page"."page_url") > 0
    and length("content_maintenance_page"."page_id") > 0
    and ("content_maintenance_page"."planned_on" is null or length("content_maintenance_page"."planned_on") = 10)
    and ("content_maintenance_page"."verified_on" is null or length("content_maintenance_page"."verified_on") = 10)
    and ("content_maintenance_page"."status" <> 'verified' or "content_maintenance_page"."verified_on" is not null)
    and ("content_maintenance_page"."status" <> 'planned' or "content_maintenance_page"."verified_on" is null)
    and length("content_maintenance_page"."created_at") between 20 and 40
    and length("content_maintenance_page"."updated_at") between 20 and 40)
);

CREATE UNIQUE INDEX `content_maintenance_page_page_uidx` ON `content_maintenance_page` (`task_id`,`page_id`);
CREATE INDEX `content_maintenance_page_task_idx` ON `content_maintenance_page` (`owner_id`,`task_id`,`channel`,`id`);
CREATE TABLE `content_maintenance_task` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`fact_version_id` text NOT NULL,
	`status` text NOT NULL,
	`reason` text NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`brand_id`,`fact_version_id`) REFERENCES `brand_fact_version`(`brand_id`,`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "content_maintenance_task_state_check" CHECK("content_maintenance_task"."status" in ('open', 'closed')
    and "content_maintenance_task"."reason" in ('expired', 'revoked')
    and length("content_maintenance_task"."created_at") between 20 and 40
    and length("content_maintenance_task"."updated_at") between 20 and 40)
);

CREATE UNIQUE INDEX `content_maintenance_task_open_uidx` ON `content_maintenance_task` (`brand_id`,`fact_version_id`) WHERE "content_maintenance_task"."status" = 'open';
CREATE INDEX `content_maintenance_task_owner_idx` ON `content_maintenance_task` (`owner_id`,`brand_id`,`updated_at`,`id`);
CREATE TABLE `content_plan` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`question_cluster` text NOT NULL,
	`coverage_json` text NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "content_plan_state_check" CHECK(length("content_plan"."question_cluster") > 0 and length("content_plan"."coverage_json") > 1)
);

CREATE INDEX `content_plan_brand_idx` ON `content_plan` (`brand_id`,`updated_at`,`id`);
CREATE INDEX `content_plan_owner_idx` ON `content_plan` (`owner_id`,`updated_at`,`id`);
CREATE UNIQUE INDEX `content_plan_cluster_uidx` ON `content_plan` (`brand_id`,`question_cluster`);
CREATE TABLE `content_publication` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`content_version_id` text NOT NULL,
	`approval_id` text NOT NULL,
	`content_fingerprint` text NOT NULL,
	`target_account` text NOT NULL,
	`page_url` text NOT NULL,
	`publisher_id` text NOT NULL,
	`claimed_published_at` text NOT NULL,
	`channel_declaration` text NOT NULL,
	`status` text NOT NULL,
	`effective_at` text,
	`evidence_grade` text,
	`superseded_by` text,
	`operation_id` text NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`content_version_id`) REFERENCES `content_version`(`id`) ON UPDATE no action ON DELETE restrict,
	FOREIGN KEY (`approval_id`) REFERENCES `content_approval`(`id`) ON UPDATE no action ON DELETE restrict,
	CONSTRAINT "content_publication_state_check" CHECK("content_publication"."status" in (
      'prepared', 'submitted', 'draft_only', 'pending_check', 'verified_public',
      'verified_manual', 'mismatch', 'access_limited', 'removed')
    and ("content_publication"."evidence_grade" is null or "content_publication"."evidence_grade" in ('public', 'manual'))
    and length("content_publication"."content_fingerprint") > 0
    and length("content_publication"."page_url") > 0
    and length("content_publication"."target_account") > 0
    and length("content_publication"."channel_declaration") > 0)
);

CREATE UNIQUE INDEX `content_publication_operation_uidx` ON `content_publication` (`brand_id`,`operation_id`);
CREATE INDEX `content_publication_version_idx` ON `content_publication` (`content_version_id`,`created_at`,`id`);
CREATE INDEX `content_publication_brand_idx` ON `content_publication` (`brand_id`,`updated_at`,`id`);
CREATE INDEX `content_publication_owner_idx` ON `content_publication` (`owner_id`,`updated_at`,`id`);
CREATE TABLE `content_publication_action` (
	`id` text PRIMARY KEY NOT NULL,
	`publication_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`kind` text NOT NULL,
	`status` text NOT NULL,
	`reason` text NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`publication_id`) REFERENCES `content_publication`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "content_publication_action_state_check" CHECK("content_publication_action"."kind" in ('repair_mismatch', 'confirm_removal', 'reverify')
    and "content_publication_action"."status" in ('open', 'done', 'cancelled')
    and length("content_publication_action"."reason") > 0)
);

CREATE INDEX `content_publication_action_publication_idx` ON `content_publication_action` (`publication_id`,`created_at`,`id`);
CREATE INDEX `content_publication_action_brand_idx` ON `content_publication_action` (`brand_id`,`updated_at`,`id`);
CREATE TABLE `content_publication_check` (
	`id` text PRIMARY KEY NOT NULL,
	`publication_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`method` text NOT NULL,
	`result_status` text NOT NULL,
	`evidence_json` text NOT NULL,
	`actor_id` text NOT NULL,
	`checked_at` text NOT NULL,
	`notes` text,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`publication_id`) REFERENCES `content_publication`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "content_publication_check_state_check" CHECK("content_publication_check"."method" in ('public_fetch', 'manual_evidence')
    and "content_publication_check"."result_status" in (
      'draft_only', 'pending_check', 'verified_public', 'verified_manual',
      'mismatch', 'access_limited', 'removed')
    and length("content_publication_check"."evidence_json") > 1)
);

CREATE INDEX `content_publication_check_publication_idx` ON `content_publication_check` (`publication_id`,`checked_at`,`id`);
CREATE INDEX `content_publication_check_brand_idx` ON `content_publication_check` (`brand_id`,`checked_at`,`id`);
CREATE TABLE `content_version` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`brief_id` text NOT NULL,
	`brief_version_id` text NOT NULL,
	`batch_unit_id` text NOT NULL,
	`template_kind` text NOT NULL,
	`title` text NOT NULL,
	`body_markdown` text NOT NULL,
	`claims_json` text NOT NULL,
	`status` text NOT NULL,
	`fingerprint` text NOT NULL,
	`created_at` text NOT NULL,
	`target_channel` text DEFAULT 'primary_page' NOT NULL,
	`labeling_profile_version` text DEFAULT 'unverified' NOT NULL,
	`labeling_profile_status` text DEFAULT 'unverified' NOT NULL,
	`image_asset_ids_json` text DEFAULT '[]' NOT NULL,
	`fact_version_ids_json` text DEFAULT '[]' NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`brief_id`) REFERENCES `content_brief`(`id`) ON UPDATE no action ON DELETE restrict,
	FOREIGN KEY (`brief_version_id`) REFERENCES `content_brief_version`(`id`) ON UPDATE no action ON DELETE restrict,
	FOREIGN KEY (`batch_unit_id`) REFERENCES `content_batch_unit`(`id`) ON UPDATE no action ON DELETE restrict,
	CONSTRAINT "content_version_state_check" CHECK("content_version"."status" in ('draft', 'in_review', 'approved', 'rejected', 'invalidated')
    and "content_version"."labeling_profile_status" in ('verified', 'unverified')
    and length("content_version"."target_channel") > 0
    and length("content_version"."labeling_profile_version") > 0
    and length("content_version"."image_asset_ids_json") > 1
    and length("content_version"."fact_version_ids_json") > 1
    and "content_version"."template_kind" in ('fact_faq', 'scenario_solution', 'verifiable_comparison')
    and length("content_version"."title") > 0
    and length("content_version"."body_markdown") > 0
    and length("content_version"."claims_json") > 1
    and length("content_version"."fingerprint") > 0)
);

CREATE INDEX `content_version_brand_idx` ON `content_version` (`brand_id`,`created_at`,`id`);
CREATE INDEX `content_version_owner_idx` ON `content_version` (`owner_id`,`created_at`,`id`);
CREATE INDEX `content_version_brief_idx` ON `content_version` (`brief_id`,`created_at`,`id`);
CREATE TABLE `report_retest` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`kind` text NOT NULL,
	`status` text NOT NULL,
	`intent` text NOT NULL,
	`track` text NOT NULL,
	`timezone` text NOT NULL,
	`entity_version` integer NOT NULL,
	`before_run_id` text,
	`after_run_id` text,
	`publication_id` text,
	`effective_at` text,
	`operation_id` text NOT NULL,
	`comparison_json` text,
	`block_reason` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "report_retest_state_check" CHECK("report_retest"."kind" in ('exploratory', 'd7_reminder', 'diagnostic')
    and "report_retest"."status" in ('scheduled', 'due', 'running', 'completed', 'inconclusive', 'blocked')
    and "report_retest"."intent" in ('business_loop', 'diagnostic')
    and "report_retest"."track" in ('model_api', 'consumer_ui')
    and "report_retest"."entity_version" > 0
    and length("report_retest"."timezone") > 0
    and length("report_retest"."operation_id") > 0)
);

CREATE UNIQUE INDEX `report_retest_operation_uidx` ON `report_retest` (`brand_id`,`operation_id`);
CREATE INDEX `report_retest_brand_idx` ON `report_retest` (`brand_id`,`updated_at`,`id`);
CREATE INDEX `report_retest_owner_idx` ON `report_retest` (`owner_id`,`updated_at`,`id`);
CREATE TABLE `report_snapshot` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`retest_id` text NOT NULL,
	`status` text NOT NULL,
	`grade` text NOT NULL,
	`intent` text NOT NULL,
	`loop_completed` integer NOT NULL,
	`predecessor_id` text,
	`entity_version` integer NOT NULL,
	`timezone` text NOT NULL,
	`locale` text NOT NULL,
	`source_missing` integer NOT NULL,
	`json_bytes` text NOT NULL,
	`html_bytes` text NOT NULL,
	`json_sha256` text NOT NULL,
	`html_sha256` text NOT NULL,
	`operation_id` text NOT NULL,
	`created_at` text NOT NULL,
	`html_object_id` text,
	`json_object_id` text,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`retest_id`) REFERENCES `report_retest`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "report_snapshot_state_check" CHECK("report_snapshot"."status" in ('created', 'superseded')
    and "report_snapshot"."grade" in ('exploratory', 'incomparable')
    and "report_snapshot"."intent" in ('business_loop', 'diagnostic')
    and "report_snapshot"."loop_completed" in (0, 1)
    and "report_snapshot"."source_missing" in (0, 1)
    and "report_snapshot"."entity_version" > 0
    and length("report_snapshot"."json_sha256") = 64
    and length("report_snapshot"."html_sha256") = 64
    and (
      ("report_snapshot"."html_object_id" is null and "report_snapshot"."json_object_id" is null
        and length("report_snapshot"."html_bytes") > 1 and length("report_snapshot"."json_bytes") > 1)
      or ("report_snapshot"."html_object_id" is not null and "report_snapshot"."json_object_id" is not null
        and "report_snapshot"."html_object_id" <> "report_snapshot"."json_object_id"
        and length("report_snapshot"."html_bytes") = 0 and length("report_snapshot"."json_bytes") = 0)
    ))
);

CREATE UNIQUE INDEX `report_snapshot_operation_uidx` ON `report_snapshot` (`brand_id`,`operation_id`);
CREATE INDEX `report_snapshot_brand_idx` ON `report_snapshot` (`brand_id`,`created_at`,`id`);
CREATE INDEX `report_snapshot_owner_idx` ON `report_snapshot` (`owner_id`,`created_at`,`id`);
CREATE INDEX `report_snapshot_predecessor_idx` ON `report_snapshot` (`predecessor_id`);
CREATE UNIQUE INDEX `report_snapshot_html_object_uidx` ON `report_snapshot` (`html_object_id`) WHERE "report_snapshot"."html_object_id" is not null;
CREATE UNIQUE INDEX `report_snapshot_json_object_uidx` ON `report_snapshot` (`json_object_id`) WHERE "report_snapshot"."json_object_id" is not null;
CREATE TABLE `report_todo` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`retest_id` text NOT NULL,
	`kind` text NOT NULL,
	`status` text NOT NULL,
	`due_at` text NOT NULL,
	`progress_json` text NOT NULL,
	`auto_charge` integer NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`retest_id`) REFERENCES `report_retest`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "report_todo_state_check" CHECK("report_todo"."kind" in ('d7_reminder')
    and "report_todo"."status" in ('scheduled', 'due', 'done', 'cancelled')
    and "report_todo"."auto_charge" = 0
    and length("report_todo"."progress_json") > 1)
);

CREATE INDEX `report_todo_brand_idx` ON `report_todo` (`brand_id`,`due_at`,`id`);
CREATE INDEX `report_todo_owner_idx` ON `report_todo` (`owner_id`,`due_at`,`id`);
CREATE TABLE `competitor_mention` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`set_id` text NOT NULL,
	`observation_id` text NOT NULL,
	`competitor_label` text NOT NULL,
	`ordered` integer NOT NULL,
	`position` integer,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`set_id`) REFERENCES `competitor_set`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`observation_id`) REFERENCES `answer_observation`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "competitor_mention_check" CHECK("competitor_mention"."ordered" in (0, 1)
    and length("competitor_mention"."competitor_label") between 1 and 80
    and (
      ("competitor_mention"."ordered" = 1 and "competitor_mention"."position" > 0)
      or ("competitor_mention"."ordered" = 0 and "competitor_mention"."position" is null)
    ))
);

CREATE UNIQUE INDEX `competitor_mention_once_uidx` ON `competitor_mention` (`set_id`,`observation_id`,`competitor_label`);
CREATE INDEX `competitor_mention_set_idx` ON `competitor_mention` (`brand_id`,`set_id`,`observation_id`);
CREATE TABLE `competitor_set` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`version` integer NOT NULL,
	`labels_json` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "competitor_set_check" CHECK("competitor_set"."version" > 0 and length("competitor_set"."labels_json") between 2 and 2000)
);

CREATE UNIQUE INDEX `competitor_set_brand_version_uidx` ON `competitor_set` (`brand_id`,`version`);
CREATE INDEX `competitor_set_owner_idx` ON `competitor_set` (`owner_id`,`brand_id`,`version`);
CREATE TABLE `research_brief` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`question_cluster` text NOT NULL,
	`gap` text NOT NULL,
	`facts_json` text NOT NULL,
	`source_ids_json` text NOT NULL,
	`status` text NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "research_brief_check" CHECK("research_brief"."status" in ('proposed', 'accepted', 'dismissed')
    and length("research_brief"."question_cluster") between 1 and 200
    and length("research_brief"."gap") between 1 and 2000
    and length("research_brief"."facts_json") between 2 and 8000
    and length("research_brief"."source_ids_json") between 2 and 4000)
);

CREATE INDEX `research_brief_brand_idx` ON `research_brief` (`brand_id`,`status`,`created_at`,`id`);
CREATE INDEX `research_brief_owner_idx` ON `research_brief` (`owner_id`,`brand_id`,`created_at`,`id`);
CREATE TABLE `source_inspection` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`citation_id` text NOT NULL,
	`state` text NOT NULL,
	`support` text NOT NULL,
	`page_live` integer NOT NULL,
	`readable` integer NOT NULL,
	`author_known` integer NOT NULL,
	`supports_brand` integer NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`citation_id`) REFERENCES `answer_citation`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "source_inspection_check" CHECK("source_inspection"."state" in ('observed', 'resolved', 'limited', 'unknown')
    and "source_inspection"."support" in ('supports', 'unknown')
    and "source_inspection"."page_live" in (0, 1)
    and "source_inspection"."readable" in (0, 1)
    and "source_inspection"."author_known" in (0, 1)
    and "source_inspection"."supports_brand" in (0, 1)
    and ("source_inspection"."support" = 'unknown' or ("source_inspection"."page_live" = 1 and "source_inspection"."readable" = 1 and "source_inspection"."supports_brand" = 1)))
);

CREATE UNIQUE INDEX `source_inspection_citation_uidx` ON `source_inspection` (`citation_id`);
CREATE INDEX `source_inspection_brand_idx` ON `source_inspection` (`brand_id`,`citation_id`);
CREATE TABLE `stored_object` (
	`id` text PRIMARY KEY NOT NULL,
	`owner_id` text NOT NULL,
	`brand_id` text,
	`class` text NOT NULL,
	`visibility` text NOT NULL,
	`status` text NOT NULL,
	`bucket` text NOT NULL,
	`object_key` text,
	`content_type` text NOT NULL,
	`byte_size` integer NOT NULL,
	`sha256` text NOT NULL,
	`file_name` text,
	`immutable` integer NOT NULL,
	`created_at` text NOT NULL,
	`ready_at` text,
	`deleted_at` text,
	CONSTRAINT "stored_object_check" CHECK("stored_object"."class" in ('internal-material', 'authorized-media', 'delivery-package', 'report-snapshot', 'owned-export', 'publication-evidence', 'source-original')
    and "stored_object"."visibility" in ('internal', 'public')
    and ("stored_object"."visibility" = 'internal' or "stored_object"."class" = 'authorized-media')
    and "stored_object"."status" in ('pending', 'ready', 'failed', 'tombstoned')
    and "stored_object"."immutable" in (0, 1)
    and (
      ("stored_object"."class" in ('delivery-package', 'report-snapshot', 'owned-export', 'publication-evidence') and "stored_object"."immutable" = 1)
      or ("stored_object"."class" in ('internal-material', 'authorized-media', 'source-original') and "stored_object"."immutable" = 0)
    )
    and (
      ("stored_object"."class" = 'owned-export' and "stored_object"."brand_id" is null and "stored_object"."byte_size" between 1 and 8388608)
      or ("stored_object"."class" <> 'owned-export' and "stored_object"."brand_id" is not null and "stored_object"."byte_size" between 1 and 10485760)
    )
    and length("stored_object"."sha256") = 64
    and "stored_object"."sha256" = lower("stored_object"."sha256")
    and length("stored_object"."bucket") between 3 and 63
    and length("stored_object"."content_type") between 3 and 255
    and length("stored_object"."created_at") between 20 and 40
    and (
      ("stored_object"."class" = 'authorized-media' and "stored_object"."content_type" in ('image/jpeg', 'image/png', 'image/webp'))
      or ("stored_object"."class" = 'publication-evidence' and "stored_object"."content_type" in ('image/jpeg', 'image/png', 'image/webp'))
      or ("stored_object"."class" = 'internal-material' and "stored_object"."content_type" in ('image/jpeg', 'image/png', 'image/webp', 'text/plain', 'text/markdown', 'application/pdf', 'application/json'))
      or ("stored_object"."class" = 'delivery-package' and "stored_object"."content_type" in ('text/markdown', 'text/html', 'application/json'))
      or ("stored_object"."class" = 'report-snapshot' and "stored_object"."content_type" in ('text/html', 'application/json'))
      or ("stored_object"."class" = 'owned-export' and "stored_object"."content_type" = 'application/json')
      or ("stored_object"."class" = 'source-original' and "stored_object"."content_type" in ('text/plain', 'text/markdown', 'application/pdf', 'application/json'))
    )
    and (
      ("stored_object"."status" = 'tombstoned' and "stored_object"."deleted_at" is not null and "stored_object"."file_name" is null and "stored_object"."object_key" is null)
      or ("stored_object"."status" in ('pending', 'failed') and "stored_object"."deleted_at" is null and "stored_object"."ready_at" is null and "stored_object"."file_name" is not null and "stored_object"."object_key" is not null)
      or ("stored_object"."status" = 'ready' and "stored_object"."deleted_at" is null and "stored_object"."ready_at" is not null and "stored_object"."file_name" is not null and "stored_object"."object_key" is not null)
    )
    and (
      "stored_object"."object_key" is null
      or (
        length("stored_object"."object_key") between 8 and 1024
        and "stored_object"."object_key" like 'v1/%'
        and "stored_object"."object_key" not like '%..%'
        and "stored_object"."file_name" is not null
        and length("stored_object"."file_name") between 1 and 120
        and "stored_object"."file_name" not like '%/%'
        and "stored_object"."file_name" not like '%..%'
      )
    )
    and ("stored_object"."ready_at" is null or length("stored_object"."ready_at") between 20 and 40)
    and ("stored_object"."deleted_at" is null or length("stored_object"."deleted_at") between 20 and 40))
);

CREATE UNIQUE INDEX `stored_object_key_uidx` ON `stored_object` (`object_key`) WHERE "stored_object"."object_key" is not null;
CREATE INDEX `stored_object_owner_idx` ON `stored_object` (`owner_id`,`brand_id`,`class`,`created_at`,`id`);
CREATE INDEX `stored_object_brand_idx` ON `stored_object` (`brand_id`,`created_at`,`id`);
CREATE INDEX `stored_object_brand_live_idx` ON `stored_object` (`brand_id`) WHERE "stored_object"."status" in ('pending', 'ready') and "stored_object"."deleted_at" is null;
CREATE TABLE `brand_storage_limit` (
	`brand_id` text PRIMARY KEY NOT NULL,
	`byte_limit` integer NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "brand_storage_limit_bytes_check" CHECK("brand_storage_limit"."byte_limit" between 1 and 2147483647)
);

CREATE TABLE `source_original` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`batch_id` text NOT NULL,
	`file_name` text NOT NULL,
	`byte_size` integer NOT NULL,
	`stored_object_id` text,
	`status` text NOT NULL,
	`reason` text,
	`rights_status` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "source_original_state_check" CHECK("source_original"."status" in ('ready', 'partial', 'failed')
    and "source_original"."rights_status" in ('active', 'revoked', 'expired')
    and ("source_original"."reason" is null or "source_original"."reason" in ('encrypted', 'oversized', 'unrecognized', 'batch_limit', 'unavailable', 'capacity'))
    and length("source_original"."file_name") between 1 and 120
    and "source_original"."file_name" not like '%/%'
    and "source_original"."file_name" not like '%..%'
    and length("source_original"."batch_id") between 1 and 64
    and length("source_original"."created_at") between 20 and 40
    and (
      ("source_original"."status" in ('ready', 'partial')
        and "source_original"."stored_object_id" is not null
        and "source_original"."reason" is null
        and "source_original"."byte_size" between 1 and 10485760)
      or ("source_original"."status" = 'failed'
        and "source_original"."stored_object_id" is null
        and "source_original"."reason" is not null
        and "source_original"."rights_status" = 'active'
        and "source_original"."byte_size" between 0 and 2147483647)
    ))
);

CREATE UNIQUE INDEX `source_original_object_uidx` ON `source_original` (`stored_object_id`) WHERE "source_original"."stored_object_id" is not null;
CREATE INDEX `source_original_owner_idx` ON `source_original` (`owner_id`,`brand_id`,`created_at`,`id`);
CREATE INDEX `source_original_brand_idx` ON `source_original` (`brand_id`,`created_at`,`id`);
CREATE TABLE `sampling_plan` (
	`id` text NOT NULL,
	`version` integer NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`phase` text NOT NULL,
	`currency` text NOT NULL,
	`budget_minor` integer NOT NULL,
	`spent_minor` integer NOT NULL,
	`pending_minor` integer NOT NULL,
	`created_at` text NOT NULL,
	PRIMARY KEY(`id`, `version`),
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "sampling_plan_state_check" CHECK("sampling_plan"."version" > 0
    and "sampling_plan"."phase" in ('draft', 'active', 'paused', 'ended')
    and length("sampling_plan"."currency") = 3
    and "sampling_plan"."budget_minor" >= 0 and "sampling_plan"."spent_minor" >= 0 and "sampling_plan"."pending_minor" >= 0
    and length("sampling_plan"."owner_id") between 1 and 128
    and length("sampling_plan"."created_at") between 20 and 40)
);

CREATE INDEX `sampling_plan_owner_idx` ON `sampling_plan` (`brand_id`,`owner_id`,`id`);
CREATE TABLE `sampling_slot` (
	`id` text PRIMARY KEY NOT NULL,
	`plan_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`channel_id` text NOT NULL,
	`at` text NOT NULL,
	`status` text NOT NULL,
	`manual` integer NOT NULL,
	`cost_minor` integer NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "sampling_slot_state_check" CHECK("sampling_slot"."status" in ('scheduled', 'completed', 'failed', 'paused')
    and "sampling_slot"."manual" in (0, 1)
    and "sampling_slot"."cost_minor" >= 0
    and length("sampling_slot"."channel_id") between 1 and 64
    and length("sampling_slot"."owner_id") between 1 and 128
    and length("sampling_slot"."at") between 20 and 40)
);

CREATE INDEX `sampling_slot_plan_at_idx` ON `sampling_slot` (`plan_id`,`at`,`id`);
CREATE TABLE `quality_alert` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`kind` text NOT NULL,
	`window_id` text NOT NULL,
	`status` text NOT NULL,
	`claim_brand_decline` integer NOT NULL,
	`reason` text NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "quality_alert_state_check" CHECK("quality_alert"."kind" in ('data_quality', 'trend')
    and "quality_alert"."status" in ('open', 'acknowledged', 'snoozed', 'resolved')
    and "quality_alert"."claim_brand_decline" in (0, 1)
    and (
      ("quality_alert"."kind" = 'data_quality' and "quality_alert"."claim_brand_decline" = 0
        and "quality_alert"."reason" in ('coverage_insufficient', 'citation_field_changed', 'mode_changed'))
      or ("quality_alert"."kind" = 'trend' and "quality_alert"."claim_brand_decline" = 1 and "quality_alert"."reason" = 'recommendation_drop')
    )
    and length("quality_alert"."window_id") between 1 and 64
    and length("quality_alert"."owner_id") between 1 and 128
    and length("quality_alert"."created_at") between 20 and 40
    and length("quality_alert"."updated_at") between 20 and 40)
);

CREATE UNIQUE INDEX `quality_alert_open_window_uidx` ON `quality_alert` (`brand_id`,`kind`,`window_id`) WHERE "quality_alert"."status" <> 'resolved';
CREATE INDEX `quality_alert_owner_idx` ON `quality_alert` (`owner_id`,`brand_id`,`updated_at`,`id`);
CREATE TABLE `quality_alert_event` (
	`id` text PRIMARY KEY NOT NULL,
	`alert_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`occurred_at` text NOT NULL,
	FOREIGN KEY (`alert_id`) REFERENCES `quality_alert`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "quality_alert_event_state_check" CHECK(length("quality_alert_event"."owner_id") between 1 and 128
    and length("quality_alert_event"."occurred_at") between 20 and 40)
);

CREATE INDEX `quality_alert_event_alert_idx` ON `quality_alert_event` (`owner_id`,`alert_id`,`occurred_at`,`id`);
CREATE TABLE `entity_review` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`observation_id` text NOT NULL,
	`analysis_version_id` text NOT NULL,
	`confirmed_error` integer NOT NULL,
	`reviewed` integer NOT NULL,
	`population_count` integer NOT NULL,
	`method` text NOT NULL,
	`fact` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "entity_review_state_check" CHECK("entity_review"."confirmed_error" in (0, 1)
    and "entity_review"."reviewed" in (0, 1)
    and "entity_review"."fact" in ('active', 'expired', 'conflict')
    and ("entity_review"."confirmed_error" = 0 or ("entity_review"."reviewed" = 1 and "entity_review"."fact" = 'active'))
    and "entity_review"."population_count" between 1 and 100000
    and length("entity_review"."method") between 1 and 200
    and length("entity_review"."owner_id") between 1 and 128
    and length("entity_review"."observation_id") = 36
    and length("entity_review"."analysis_version_id") = 36
    and length("entity_review"."created_at") between 20 and 40)
);

CREATE UNIQUE INDEX `entity_review_sample_uidx` ON `entity_review` (`observation_id`,`analysis_version_id`,`created_at`);
CREATE INDEX `entity_review_owner_idx` ON `entity_review` (`owner_id`,`brand_id`,`observation_id`,`analysis_version_id`,`created_at`,`id`);
CREATE TABLE `entity_correction` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`observation_id` text NOT NULL,
	`action` text NOT NULL,
	`effect` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`observation_id`) REFERENCES `answer_observation`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "entity_correction_state_check" CHECK((("entity_correction"."action" = 'open' and "entity_correction"."effect" in ('open', 'unresolved'))
      or ("entity_correction"."action" = 'actioned' and "entity_correction"."effect" in ('pending_retest', 'unresolved')))
    and length("entity_correction"."owner_id") between 1 and 128
    and length("entity_correction"."observation_id") = 36
    and length("entity_correction"."created_at") between 20 and 40)
);

CREATE UNIQUE INDEX `entity_correction_event_uidx` ON `entity_correction` (`observation_id`,`created_at`);
CREATE INDEX `entity_correction_owner_idx` ON `entity_correction` (`owner_id`,`brand_id`,`created_at`,`id`);
CREATE TABLE `entity_disambiguation` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`observation_id` text NOT NULL,
	`prior_analysis_id` text NOT NULL,
	`next_analysis_id` text NOT NULL,
	`count_as_target_mention` integer NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`observation_id`) REFERENCES `answer_observation`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`prior_analysis_id`) REFERENCES `answer_analysis_version`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`next_analysis_id`) REFERENCES `answer_analysis_version`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "entity_disambiguation_state_check" CHECK("entity_disambiguation"."count_as_target_mention" = 0
    and "entity_disambiguation"."prior_analysis_id" <> "entity_disambiguation"."next_analysis_id"
    and length("entity_disambiguation"."owner_id") between 1 and 128
    and length("entity_disambiguation"."observation_id") = 36
    and length("entity_disambiguation"."prior_analysis_id") = 36
    and length("entity_disambiguation"."next_analysis_id") = 36
    and length("entity_disambiguation"."created_at") between 20 and 40)
);

CREATE UNIQUE INDEX `entity_disambiguation_prior_uidx` ON `entity_disambiguation` (`prior_analysis_id`);
CREATE UNIQUE INDEX `entity_disambiguation_next_uidx` ON `entity_disambiguation` (`next_analysis_id`);
