CREATE TABLE `formal_checkpoint` (
	`id` text PRIMARY KEY NOT NULL,
	`observation_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`checkpoint` text NOT NULL,
	`mode` text NOT NULL,
	`comparable_count` integer NOT NULL,
	`excluded_json` text NOT NULL,
	`conclusion` text,
	`evaluated_on` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`observation_id`) REFERENCES `formal_observation`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "formal_checkpoint_state_check" CHECK("formal_checkpoint"."checkpoint" in ('d7', 'd14', 'd28')
    and "formal_checkpoint"."mode" in ('progress', 'formal', 'exploratory')
    and "formal_checkpoint"."comparable_count" between 0 and 500
    and length("formal_checkpoint"."excluded_json") between 2 and 4000
    and length("formal_checkpoint"."evaluated_on") = 10
    and (
      ("formal_checkpoint"."mode" = 'progress' and "formal_checkpoint"."conclusion" is null)
      or ("formal_checkpoint"."mode" in ('formal', 'exploratory') and "formal_checkpoint"."conclusion" is not null
        and length("formal_checkpoint"."conclusion") between 2 and 400)
    )
    and length("formal_checkpoint"."owner_id") between 1 and 128
    and length("formal_checkpoint"."created_at") between 20 and 40)
);

CREATE INDEX `formal_checkpoint_observation_idx` ON `formal_checkpoint` (`owner_id`,`observation_id`,`created_at`,`id`);
CREATE TABLE `formal_confounder` (
	`id` text PRIMARY KEY NOT NULL,
	`observation_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`factor` text NOT NULL,
	`note` text NOT NULL,
	`recorded_at` text NOT NULL,
	FOREIGN KEY (`observation_id`) REFERENCES `formal_observation`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "formal_confounder_state_check" CHECK("formal_confounder"."factor" in ('model', 'marketing', 'price')
    and length(trim("formal_confounder"."note")) between 1 and 400
    and length("formal_confounder"."owner_id") between 1 and 128
    and length("formal_confounder"."recorded_at") between 20 and 40)
);

CREATE INDEX `formal_confounder_observation_idx` ON `formal_confounder` (`owner_id`,`observation_id`,`recorded_at`,`id`);
CREATE TABLE `formal_observation` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`frozen_set_id` text NOT NULL,
	`effective_on` text NOT NULL,
	`frozen_non_brand_count` integer NOT NULL,
	`status` text NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "formal_observation_state_check" CHECK("formal_observation"."status" in ('observing', 'checkpoint_due')
    and "formal_observation"."frozen_non_brand_count" between 1 and 500
    and length("formal_observation"."frozen_set_id") between 1 and 64
    and length("formal_observation"."effective_on") = 10
    and length("formal_observation"."owner_id") between 1 and 128
    and length("formal_observation"."created_at") between 20 and 40
    and length("formal_observation"."updated_at") between 20 and 40)
);

CREATE INDEX `formal_observation_owner_idx` ON `formal_observation` (`owner_id`,`brand_id`,`created_at`,`id`);
CREATE TABLE `assistant_plan` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`material_hash` text NOT NULL,
	`status` text NOT NULL,
	`controls_unchanged` integer NOT NULL,
	`ignored` integer NOT NULL,
	`budget_minor` integer NOT NULL,
	`strategy_label` text NOT NULL,
	`guaranteed` integer NOT NULL,
	`successes` integer NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "assistant_plan_state_check" CHECK("assistant_plan"."status" in ('draft', 'settled')
    and "assistant_plan"."controls_unchanged" = 1
    and "assistant_plan"."ignored" in (0, 1)
    and "assistant_plan"."budget_minor" between 0 and 1000000000
    and "assistant_plan"."strategy_label" = 'observation'
    and "assistant_plan"."guaranteed" = 0
    and "assistant_plan"."successes" between 0 and 1000000
    and length("assistant_plan"."material_hash") = 64
    and length("assistant_plan"."owner_id") between 1 and 128
    and length("assistant_plan"."created_at") between 20 and 40
    and length("assistant_plan"."updated_at") between 20 and 40)
);

CREATE INDEX `assistant_plan_owner_idx` ON `assistant_plan` (`owner_id`,`brand_id`,`created_at`,`id`);
CREATE TABLE `assistant_plan_item` (
	`id` text PRIMARY KEY NOT NULL,
	`plan_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`position` integer NOT NULL,
	`action_text` text NOT NULL,
	`fact_version_id` text NOT NULL,
	`fact_current` integer NOT NULL,
	`status` text NOT NULL,
	`block_reason` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`plan_id`) REFERENCES `assistant_plan`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`brand_id`,`fact_version_id`) REFERENCES `brand_fact_version`(`brand_id`,`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "assistant_plan_item_state_check" CHECK("assistant_plan_item"."position" between 1 and 5
    and "assistant_plan_item"."fact_current" in (0, 1)
    and "assistant_plan_item"."status" in ('draft', 'confirmed', 'executed', 'blocked')
    and (
      ("assistant_plan_item"."status" = 'blocked' and "assistant_plan_item"."block_reason" = 'fact_stale')
      or ("assistant_plan_item"."status" <> 'blocked' and "assistant_plan_item"."block_reason" is null)
    )
    and length("assistant_plan_item"."action_text") between 1 and 200
    and length("assistant_plan_item"."fact_version_id") between 1 and 64
    and length("assistant_plan_item"."owner_id") between 1 and 128
    and length("assistant_plan_item"."created_at") between 20 and 40
    and length("assistant_plan_item"."updated_at") between 20 and 40)
);

CREATE UNIQUE INDEX `assistant_plan_item_position_uidx` ON `assistant_plan_item` (`plan_id`,`position`);
CREATE INDEX `assistant_plan_item_owner_idx` ON `assistant_plan_item` (`owner_id`,`plan_id`,`position`);
CREATE TABLE `business_lead` (
