	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "lead_question_suggestion_state_check" CHECK("lead_question_suggestion"."status" in ('draft', 'accepted', 'discarded')
    and "lead_question_suggestion"."injection_ignored" in (0, 1)
    and length("lead_question_suggestion"."summary_hash") = 64
    and length("lead_question_suggestion"."model_name") between 1 and 128
    and length("lead_question_suggestion"."suggestion_json") between 20 and 2000
    and length("lead_question_suggestion"."owner_id") between 1 and 128
    and length("lead_question_suggestion"."created_at") between 20 and 40)
);

CREATE INDEX `lead_question_suggestion_owner_idx` ON `lead_question_suggestion` (`owner_id`,`brand_id`,`created_at`,`id`);
CREATE TABLE `brand_member_grant` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`role` text NOT NULL,
	`active` integer NOT NULL,
	`expires_at` text,
	`created_at` text NOT NULL,
	`revoked_at` text,
	FOREIGN KEY (`user_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "brand_member_grant_state_check" CHECK("brand_member_grant"."role" in ('owner', 'member')
    and "brand_member_grant"."active" in (0, 1)
    and length("brand_member_grant"."user_id") between 1 and 128
    and length("brand_member_grant"."created_at") between 20 and 40
    and ("brand_member_grant"."expires_at" is null or length("brand_member_grant"."expires_at") between 20 and 40)
    and (("brand_member_grant"."active" = 1 and "brand_member_grant"."revoked_at" is null)
      or ("brand_member_grant"."active" = 0 and length("brand_member_grant"."revoked_at") between 20 and 40)))
);

CREATE UNIQUE INDEX `brand_member_grant_pair_uidx` ON `brand_member_grant` (`user_id`,`brand_id`);
CREATE INDEX `brand_member_grant_user_idx` ON `brand_member_grant` (`user_id`,`brand_id`) WHERE "brand_member_grant"."active" = 1;
CREATE INDEX `brand_member_grant_brand_idx` ON `brand_member_grant` (`brand_id`,`user_id`);
CREATE TABLE `brand_owner_transfer` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`from_user_id` text NOT NULL,
	`to_user_id` text NOT NULL,
	`actor_id` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`from_user_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`to_user_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`actor_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "brand_owner_transfer_state_check" CHECK("brand_owner_transfer"."from_user_id" <> "brand_owner_transfer"."to_user_id"
    and length("brand_owner_transfer"."from_user_id") between 1 and 128
    and length("brand_owner_transfer"."to_user_id") between 1 and 128
    and length("brand_owner_transfer"."actor_id") between 1 and 128
    and length("brand_owner_transfer"."created_at") between 20 and 40)
);

