	`owner_id` text NOT NULL,
	`page_key` text NOT NULL,
	`verified_at` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`batch_id`) REFERENCES `intervention_batch`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "intervention_batch_page_state_check" CHECK(length("intervention_batch_page"."id") = 36
    and length("intervention_batch_page"."batch_id") = 36
    and length("intervention_batch_page"."brand_id") = 36
    and length("intervention_batch_page"."owner_id") between 1 and 128
    and length("intervention_batch_page"."page_key") between 1 and 300
    and ("intervention_batch_page"."verified_at" is null or length("intervention_batch_page"."verified_at") between 20 and 40)
    and length("intervention_batch_page"."created_at") between 20 and 40
    and length("intervention_batch_page"."updated_at") between 20 and 40)
);

CREATE UNIQUE INDEX `intervention_batch_page_key_uidx` ON `intervention_batch_page` (`batch_id`,`page_key`);
CREATE TABLE `capture_attempt` (
	`id` text PRIMARY KEY NOT NULL,
	`sheet_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`blocked_by` text,
	`citation_count` integer NOT NULL,
	`status` text NOT NULL,
	`confirmed` integer NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`sheet_id`) REFERENCES `capture_sheet`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "capture_attempt_state_check" CHECK("capture_attempt"."status" in ('handoff', 'partial', 'preview')
    and "capture_attempt"."confirmed" in (0, 1)
    and "capture_attempt"."citation_count" between 0 and 1000
    and (
      ("capture_attempt"."blocked_by" in ('captcha', 'login') and "capture_attempt"."status" = 'handoff' and "capture_attempt"."confirmed" = 0)
      or ("capture_attempt"."blocked_by" is null and "capture_attempt"."citation_count" = 0 and "capture_attempt"."status" = 'partial')
      or ("capture_attempt"."blocked_by" is null and "capture_attempt"."citation_count" between 1 and 1000 and "capture_attempt"."status" = 'preview')
    )
    and length("capture_attempt"."id") = 36
    and length("capture_attempt"."sheet_id") = 36
    and length("capture_attempt"."brand_id") = 36
    and length("capture_attempt"."owner_id") between 1 and 128
    and ("capture_attempt"."blocked_by" is null or length("capture_attempt"."blocked_by") between 5 and 7)
    and length("capture_attempt"."created_at") between 20 and 40
    and length("capture_attempt"."updated_at") between 20 and 40)
);

CREATE INDEX `capture_attempt_sheet_idx` ON `capture_attempt` (`owner_id`,`sheet_id`,`created_at`,`id`);
CREATE TABLE `capture_sheet` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`prompt_ids_json` text NOT NULL,
	`mode` text NOT NULL,
	`assisted_minutes` integer,
	`manual_minutes` integer,
	`citations_complete` integer NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "capture_sheet_state_check" CHECK("capture_sheet"."mode" in ('assisted', 'manual')
    and "capture_sheet"."citations_complete" in (0, 1)
    and ("capture_sheet"."assisted_minutes" is null or "capture_sheet"."assisted_minutes" between 0 and 100000)
    and ("capture_sheet"."manual_minutes" is null or "capture_sheet"."manual_minutes" between 0 and 100000)
    and length("capture_sheet"."prompt_ids_json") between 40 and 8000
    and length("capture_sheet"."id") = 36
    and length("capture_sheet"."brand_id") = 36
    and length("capture_sheet"."owner_id") between 1 and 128
    and length("capture_sheet"."created_at") between 20 and 40
    and length("capture_sheet"."updated_at") between 20 and 40)
);

CREATE INDEX `capture_sheet_owner_idx` ON `capture_sheet` (`owner_id`,`brand_id`,`created_at`,`id`);
CREATE TABLE `external_action` (
	`id` text PRIMARY KEY NOT NULL,
	`connection_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`idempotency_key` text NOT NULL,
	`confirmed` integer NOT NULL,
	`status` text NOT NULL,
	`receipt_kind` text,
	`effective_at` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`connection_id`) REFERENCES `external_connection`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "external_action_state_check" CHECK("external_action"."confirmed" in (0, 1)
    and "external_action"."status" in ('confirmed', 'acknowledged', 'unknown', 'failed', 'reconciled')
    and ("external_action"."receipt_kind" is null or "external_action"."receipt_kind" in ('draft_created', 'public_url'))
    and length("external_action"."id") = 36
    and length("external_action"."connection_id") = 36
    and length("external_action"."brand_id") = 36
    and length("external_action"."owner_id") between 1 and 128
    and length("external_action"."idempotency_key") between 8 and 80
    and length("external_action"."created_at") between 20 and 40
    and length("external_action"."updated_at") between 20 and 40
    and (
      ("external_action"."status" = 'failed' and "external_action"."receipt_kind" is null and "external_action"."effective_at" is null)
      or ("external_action"."status" in ('confirmed', 'unknown') and "external_action"."confirmed" = 1 and "external_action"."receipt_kind" is null and "external_action"."effective_at" is null)
      or (
        "external_action"."status" in ('acknowledged', 'reconciled')
        and "external_action"."confirmed" = 1
        and (
          ("external_action"."receipt_kind" is null and "external_action"."effective_at" is null)
          or ("external_action"."receipt_kind" = 'draft_created' and "external_action"."effective_at" is null)
          or ("external_action"."receipt_kind" = 'public_url' and "external_action"."effective_at" is not null and length("external_action"."effective_at") between 20 and 40)
        )
      )
    ))
);

CREATE UNIQUE INDEX `external_action_key_uidx` ON `external_action` (`connection_id`,`idempotency_key`);
CREATE INDEX `external_action_connection_idx` ON `external_action` (`owner_id`,`connection_id`,`created_at`,`id`);
CREATE TABLE `external_connection` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`label` text NOT NULL,
	`can_read` integer NOT NULL,
	`can_draft` integer NOT NULL,
	`can_publish` integer NOT NULL,
	`status` text NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "external_connection_state_check" CHECK("external_connection"."status" in ('pending', 'verified', 'revoked')
    and "external_connection"."can_read" in (0, 1)
    and "external_connection"."can_draft" in (0, 1)
    and "external_connection"."can_publish" in (0, 1)
    and length("external_connection"."id") = 36
    and length("external_connection"."brand_id") = 36
    and length("external_connection"."owner_id") between 1 and 128
    and length("external_connection"."label") between 1 and 80
    and length("external_connection"."created_at") between 20 and 40
    and length("external_connection"."updated_at") between 20 and 40)
);

CREATE INDEX `external_connection_owner_idx` ON `external_connection` (`owner_id`,`brand_id`,`created_at`,`id`);
CREATE TABLE `notification_delivery` (
	`id` text PRIMARY KEY NOT NULL,
	`endpoint_id` text NOT NULL,
