	`id` text PRIMARY KEY NOT NULL,
	`event_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`source` text NOT NULL,
	`payload_digest` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`owner_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`event_id`) REFERENCES `connector_event`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "connector_event_source_state_check" CHECK("connector_event_source"."source" in ('csv', 'connector')
    and length("connector_event_source"."payload_digest") = 64
    and "connector_event_source"."payload_digest" not glob '*[^a-f0-9]*'
    and length("connector_event_source"."id") = 36
    and length("connector_event_source"."event_id") = 36
    and length("connector_event_source"."brand_id") = 36
    and length("connector_event_source"."owner_id") between 1 and 128
    and length("connector_event_source"."created_at") between 20 and 40)
);

CREATE UNIQUE INDEX `connector_event_source_event_uidx` ON `connector_event_source` (`event_id`,`source`);
CREATE INDEX `connector_event_source_owner_idx` ON `connector_event_source` (`owner_id`,`event_id`,`source`);
CREATE TABLE `crawler_observation` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`identity` text NOT NULL,
	`citations` integer NOT NULL,
	`called_included` integer NOT NULL,
	`observed_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`owner_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "crawler_observation_state_check" CHECK("crawler_observation"."identity" in ('unverified', 'verified')
    and "crawler_observation"."citations" between 0 and 1000000000
    and "crawler_observation"."called_included" = 0
    and length("crawler_observation"."id") = 36
    and length("crawler_observation"."brand_id") = 36
    and length("crawler_observation"."owner_id") between 1 and 128
    and length("crawler_observation"."observed_at") between 20 and 40)
);

CREATE INDEX `crawler_observation_owner_idx` ON `crawler_observation` (`owner_id`,`observed_at`,`id`);
CREATE TABLE `sync_attempt` (
	`id` text PRIMARY KEY NOT NULL,
	`authorization_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`result` text NOT NULL,
	`attempted_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`owner_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`authorization_id`) REFERENCES `sync_authorization`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "sync_attempt_state_check" CHECK("sync_attempt"."result" in ('allowed', 'stopped')
    and length("sync_attempt"."id") = 36
    and length("sync_attempt"."authorization_id") = 36
    and length("sync_attempt"."brand_id") = 36
    and length("sync_attempt"."owner_id") between 1 and 128
    and length("sync_attempt"."attempted_at") between 20 and 40)
);

CREATE INDEX `sync_attempt_owner_idx` ON `sync_attempt` (`owner_id`,`authorization_id`,`attempted_at`,`id`);
CREATE TABLE `sync_authorization` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`source_name` text NOT NULL,
	`revoked` integer NOT NULL,
	`retained_rows` integer NOT NULL,
	`history_deleted` integer NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`owner_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "sync_authorization_state_check" CHECK("sync_authorization"."revoked" in (0, 1)
    and "sync_authorization"."history_deleted" = 0
    and "sync_authorization"."retained_rows" between 0 and 1000000000
    and length("sync_authorization"."source_name") between 1 and 80
    and length("sync_authorization"."id") = 36
    and length("sync_authorization"."brand_id") = 36
    and length("sync_authorization"."owner_id") between 1 and 128
    and length("sync_authorization"."created_at") between 20 and 40
    and length("sync_authorization"."updated_at") between 20 and 40)
);

CREATE INDEX `sync_authorization_owner_idx` ON `sync_authorization` (`owner_id`,`created_at`,`id`);
CREATE TABLE `local_observation` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`target_city` text NOT NULL,
	`sampled_city` text,
	`ranked` integer NOT NULL,
	`claimed_local_users` integer NOT NULL,
	`recorded_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`owner_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "local_observation_state_check" CHECK("local_observation"."ranked" = 0
    and "local_observation"."claimed_local_users" = 0
    and length("local_observation"."target_city") between 1 and 80
    and ("local_observation"."sampled_city" is null or length("local_observation"."sampled_city") between 1 and 80)
    and length("local_observation"."id") = 36
    and length("local_observation"."brand_id") = 36
    and length("local_observation"."owner_id") between 1 and 128
    and length("local_observation"."recorded_at") between 20 and 40)
);

CREATE INDEX `local_observation_owner_idx` ON `local_observation` (`owner_id`,`recorded_at`,`id`);
CREATE TABLE `brand_store` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`name` text NOT NULL,
	`service_area` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`owner_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "brand_store_state_check" CHECK(length("brand_store"."id") = 36
    and length("brand_store"."brand_id") = 36
    and length("brand_store"."owner_id") between 1 and 128
    and length("brand_store"."name") between 1 and 80
    and length("brand_store"."service_area") between 1 and 160
    and length("brand_store"."created_at") between 20 and 40)
);

CREATE INDEX `brand_store_owner_brand_idx` ON `brand_store` (`owner_id`,`brand_id`,`created_at`,`id`);
CREATE TABLE `store_fact_use` (
	`id` text PRIMARY KEY NOT NULL,
	`store_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`service_area` text NOT NULL,
	`used_other_store` integer NOT NULL,
	`recorded_at` text NOT NULL,
	FOREIGN KEY (`store_id`) REFERENCES `brand_store`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`owner_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "store_fact_use_state_check" CHECK("store_fact_use"."used_other_store" = 0
    and length("store_fact_use"."id") = 36
    and length("store_fact_use"."store_id") = 36
    and length("store_fact_use"."owner_id") between 1 and 128
    and length("store_fact_use"."service_area") between 1 and 160
    and length("store_fact_use"."recorded_at") between 20 and 40)
);

CREATE INDEX `store_fact_use_owner_idx` ON `store_fact_use` (`owner_id`,`recorded_at`,`id`);
CREATE TABLE `media_review` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`kind` text NOT NULL,
	`shown_value` text NOT NULL,
	`approved_value` text NOT NULL,
	`fact_version_id` text NOT NULL,
	`reason` text NOT NULL,
	`deliver` integer NOT NULL,
	`recorded_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`owner_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`brand_id`,`fact_version_id`) REFERENCES `brand_fact_version`(`brand_id`,`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "media_review_state_check" CHECK("media_review"."deliver" in (0, 1)
    and "media_review"."kind" in ('image', 'script')
    and "media_review"."reason" in ('ok', 'fact_mismatch', 'not_proof')
    and (
      ("media_review"."reason" = 'ok' and "media_review"."deliver" = 1 and "media_review"."shown_value" = "media_review"."approved_value")
      or ("media_review"."reason" = 'fact_mismatch' and "media_review"."deliver" = 0 and "media_review"."shown_value" <> "media_review"."approved_value")
      or ("media_review"."reason" = 'not_proof' and "media_review"."deliver" = 0)
    )
    and length("media_review"."id") = 36
    and length("media_review"."brand_id") = 36
    and length("media_review"."owner_id") between 1 and 128
    and length("media_review"."fact_version_id") = 36
    and length("media_review"."shown_value") between 1 and 4000
    and length("media_review"."approved_value") between 1 and 4000
    and length("media_review"."recorded_at") between 20 and 40)
);

CREATE INDEX `media_review_owner_idx` ON `media_review` (`owner_id`,`recorded_at`,`id`);
CREATE INDEX `media_review_owner_brand_idx` ON `media_review` (`owner_id`,`brand_id`,`recorded_at`,`id`);
CREATE TABLE `brand_delivery` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`title` text NOT NULL,
	`status` text NOT NULL,
	`dispute_reason` text,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`owner_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "brand_delivery_state_check" CHECK("brand_delivery"."status" in ('pending', 'accepted', 'disputed')
    and (("brand_delivery"."status" = 'disputed' and "brand_delivery"."dispute_reason" is not null and length("brand_delivery"."dispute_reason") between 1 and 500)
      or ("brand_delivery"."status" in ('pending', 'accepted') and "brand_delivery"."dispute_reason" is null))
    and length("brand_delivery"."title") between 1 and 120
    and length("brand_delivery"."id") = 36
    and length("brand_delivery"."brand_id") = 36
    and length("brand_delivery"."owner_id") between 1 and 128
    and length("brand_delivery"."created_at") between 20 and 40)
);

CREATE INDEX `brand_delivery_owner_idx` ON `brand_delivery` (`owner_id`,`created_at`,`id`);
CREATE TABLE `entitlement_usage` (
	`id` text PRIMARY KEY NOT NULL,
	`entitlement_id` text NOT NULL,
	`kind` text NOT NULL,
	`quantity` integer NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`entitlement_id`) REFERENCES `service_entitlement`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "entitlement_usage_state_check" CHECK("entitlement_usage"."kind" in ('monitoring', 'content', 'labor')
    and "entitlement_usage"."quantity" between 1 and 1000000
    and length("entitlement_usage"."id") = 36
    and length("entitlement_usage"."entitlement_id") = 36
    and length("entitlement_usage"."created_at") between 20 and 40)
);

CREATE INDEX `entitlement_usage_entitlement_idx` ON `entitlement_usage` (`entitlement_id`,`created_at`,`id`);
CREATE TABLE `service_entitlement` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`version` integer NOT NULL,
	`kind` text NOT NULL,
	`monitoring_quota` integer NOT NULL,
	`content_quota` integer NOT NULL,
	`labor_quota` integer NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`owner_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "service_entitlement_state_check" CHECK("service_entitlement"."kind" in ('trial', 'quote')
    and "service_entitlement"."version" between 1 and 1000000
    and "service_entitlement"."monitoring_quota" between 0 and 1000000
    and "service_entitlement"."content_quota" between 0 and 1000000
    and "service_entitlement"."labor_quota" between 0 and 1000000
    and length("service_entitlement"."id") = 36
    and length("service_entitlement"."brand_id") = 36
    and length("service_entitlement"."owner_id") between 1 and 128
    and length("service_entitlement"."created_at") between 20 and 40)
);

CREATE UNIQUE INDEX `service_entitlement_brand_kind_version_uidx` ON `service_entitlement` (`brand_id`,`kind`,`version`);
CREATE INDEX `service_entitlement_owner_idx` ON `service_entitlement` (`owner_id`,`created_at`,`id`);
CREATE TABLE `industry_pack` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`scope` text NOT NULL,
	`covers_regulated` integer NOT NULL,
	`status` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`owner_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "industry_pack_state_check" CHECK("industry_pack"."covers_regulated" in (0, 1)
    and "industry_pack"."status" in ('draft', 'reviewed', 'available', 'retired')
    and length("industry_pack"."id") = 36
    and length("industry_pack"."brand_id") = 36
    and length("industry_pack"."owner_id") between 1 and 128
    and length("industry_pack"."scope") between 1 and 400
    and length("industry_pack"."created_at") between 20 and 40)
);

CREATE INDEX `industry_pack_owner_idx` ON `industry_pack` (`owner_id`,`created_at`,`id`);
CREATE INDEX `industry_pack_owner_brand_idx` ON `industry_pack` (`owner_id`,`brand_id`,`created_at`,`id`);
CREATE TABLE `industry_pack_question` (
	`id` text PRIMARY KEY NOT NULL,
	`pack_id` text NOT NULL,
	`body` text NOT NULL,
	`status` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`pack_id`) REFERENCES `industry_pack`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "industry_pack_question_state_check" CHECK("industry_pack_question"."status" = 'draft'
    and length("industry_pack_question"."id") = 36
    and length("industry_pack_question"."pack_id") = 36
    and length("industry_pack_question"."body") between 1 and 500
    and length("industry_pack_question"."created_at") between 20 and 40)
);

CREATE INDEX `industry_pack_question_pack_idx` ON `industry_pack_question` (`pack_id`,`created_at`,`id`);
